const e=JSON.parse(`[{"id":"upsc-2018-prelims-gs1-c-001","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":1,"booklet":"C","questionType":"MCQ","subject":"History","topic":"Modern India · people, publications & events","question":"Consider the following events:\\n\\n1. The first democratically elected communist party government formed in a State in India.\\n\\n2. India’s then largest bank, ‘Imperial Bank of India’ was renamed ‘State Bank of India’.\\n\\n3. Air India was nationalized and became the national carrier.\\n\\n4. Goa became a part of independent India.\\n\\nWhich of the following is the correct chronological sequence of the above events?","options":{"a":"4-1-2-3","b":"3-2-1-4","c":"4-2-1-3","d":"3-1-2-4"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Consider the following events:"},{"type":"paragraph","text":"1. The first democratically elected communist party government formed in a State in India."},{"type":"paragraph","text":"2. India’s then largest bank, ‘Imperial Bank of India’ was renamed ‘State Bank of India’."},{"type":"paragraph","text":"3. Air India was nationalized and became the national carrier."},{"type":"paragraph","text":"4. Goa became a part of independent India."},{"type":"paragraph","text":"Which of the following is the correct chronological sequence of the above events?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"The correct chronological order is: Air India was nationalised (1953), Imperial Bank became SBI (July 1955), First Communist government formed in Kerala (April 1957), and Goa was liberated/became part of India (Dec 1961).","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-002","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":2,"booklet":"C","questionType":"MCQ","subject":"Polity & Governance","topic":"Right to privacy","question":"Right of Privacy is protected as an intrinsic part of Right to Life and Personal Liberty. Which of the following in the Constitution of India correctly and appropriately imply the above statement?","options":{"a":"Article 14 and the provisions under the 42nd Amendment to the Constitution","b":"Article 17 and the Directive Principles of State Policy in part IV","c":"Article 21 and the freedoms guaranteed in Part III","d":"Article 24 and the provisions under the 44th Amendment to the Constitution"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Right of Privacy is protected as an intrinsic part of Right to Life and Personal Liberty. Which of the following in the Constitution of India correctly and appropriately imply the above statement?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"The Supreme Court recognised privacy as a Fundamental Right in the 2017 Puttaswamy judgment. It is protected through Article 21’s guarantees of life and personal liberty and the freedoms in Part III of the Constitution.","concept":"Right to privacy","references":[{"title":"UPSC CSE2018 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2018-prelims-gs1-c-003","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":3,"booklet":"C","questionType":"MCQ","subject":"Economy","topic":"Agriculture & allied sectors","question":"Consider the following:\\n\\n1. Areca nut\\n\\n2. Barley\\n\\n3. Coffee\\n\\n4. Finger millet\\n\\n5. Groundnut\\n\\n6. Sesamum\\n\\n7. Turmeric\\n\\nThe Cabinet Committee on Economic Affairs has announced the Minimum Support Price for which of the above?","options":{"a":"1, 2, 3 and 7 only","b":"2, 4, 5 and 6 only","c":"1, 3, 4, 5 and 6 only","d":"1, 2, 3, 4, 5, 6 and 7"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Consider the following:"},{"type":"paragraph","text":"1. Areca nut"},{"type":"paragraph","text":"2. Barley"},{"type":"paragraph","text":"3. Coffee"},{"type":"paragraph","text":"4. Finger millet"},{"type":"paragraph","text":"5. Groundnut"},{"type":"paragraph","text":"6. Sesamum"},{"type":"paragraph","text":"7. Turmeric"},{"type":"paragraph","text":"The Cabinet Committee on Economic Affairs has announced the Minimum Support Price for which of the above?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"The government announces MSP for 22 mandated crops (plus FRP for sugarcane). Out of the listed items, Barley (cereal), Finger millet (cereal), Groundnut (oilseed), and Sesamum (oilseed) are covered under the official MSP list. Areca nut, Coffee (a plantation crop), and Turmeric (a spice) are NOT covered under the MSP regime.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-004","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":4,"booklet":"C","questionType":"MCQ","subject":"Environment","topic":"Climate action & agreements","question":"In which one of the following States is Pakhui Wildlife Sanctuary located?","options":{"a":"Arunachal Pradesh","b":"Manipur","c":"Meghalaya","d":"Nagaland"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"In which one of the following States is Pakhui Wildlife Sanctuary located?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"Pakhui Wildlife Sanctuary (also known as Pakke Tiger Reserve) is located in the foothills of the Eastern Himalayas in the East Kameng district of Arunachal Pradesh.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-005","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":5,"booklet":"C","questionType":"MCQ","subject":"Science & Technology","topic":"Applied science & technology","question":"With reference to India’s satellite launch vehicles, consider the following statement:\\n\\n1. PSLVs launch the satellites useful for Earth resources monitoring whereas GSLVs are designed mainly to launch communication satellites.\\n\\n2. Satellites launched by PSLV appear to remain permanently fixed in the same position in the sky, as viewed from a particular location on Earth.\\n\\n3. GSLV MK III is a four staged launch vehicle with the first and third stages using solid rocket motors; and the second and fourth stages using liquid rocket engines.\\n\\nWhich of the statements given above is/are correct?","options":{"a":"1 only","b":"2 and 3 only","c":"1 and 2 only","d":"3 only"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"With reference to India’s satellite launch vehicles, consider the following statement:"},{"type":"paragraph","text":"1. PSLVs launch the satellites useful for Earth resources monitoring whereas GSLVs are designed mainly to launch communication satellites."},{"type":"paragraph","text":"2. Satellites launched by PSLV appear to remain permanently fixed in the same position in the sky, as viewed from a particular location on Earth."},{"type":"paragraph","text":"3. GSLV MK III is a four staged launch vehicle with the first and third stages using solid rocket motors; and the second and fourth stages using liquid rocket engines."},{"type":"paragraph","text":"Which of the statements given above is/are correct?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"PSLV is heavily used for polar/earth observation satellites, while GSLV places heavier communication satellites into geosynchronous orbits (Statement 1 is true). Geosynchronous satellites (launched by GSLV, not PSLV) appear fixed in the sky. GSLV Mk III is a three-stage, not a four-stage, vehicle.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-006","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":6,"booklet":"C","questionType":"MCQ","subject":"Economy","topic":"Public finance & fiscal policy","question":"With reference to the governance of public sector banking in India, consider the following statements:\\n\\n1. Capital infusion into public sector banks by the Government of India has steadily increased in the last decade.\\n\\n2. To put the public sector banks in order, the merger of associate banks with the parent State Bank of India has been affected.\\n\\nWhich of the statements given above is/are correct?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"With reference to the governance of public sector banking in India, consider the following statements:"},{"type":"paragraph","text":"1. Capital infusion into public sector banks by the Government of India has steadily increased in the last decade."},{"type":"paragraph","text":"2. To put the public sector banks in order, the merger of associate banks with the parent State Bank of India has been affected."},{"type":"paragraph","text":"Which of the statements given above is/are correct?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"Statement 1 is incorrect because capital infusion into public sector banks has shown a fluctuating trend over the decade rather than steadily increasing. Statement 2 is correct as associate banks were merged with the State Bank of India to consolidate and strengthen public sector banking.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-007","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":7,"booklet":"C","questionType":"MCQ","subject":"Economy","topic":"Public finance & fiscal policy","question":"Consider the following items:\\n\\n1. Cereal grains hulled\\n\\n2. Chicken eggs cooked\\n\\n3. Fish processed and canned\\n\\n4. Newspapers containing advertising material\\n\\nWhich of the above items is/are exempted under GST (Goods and Services Tax)?","options":{"a":"1 only","b":"2 and 3 only","c":"1, 2 and 4 only","d":"1, 2, 3 and 4"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Consider the following items:"},{"type":"paragraph","text":"1. Cereal grains hulled"},{"type":"paragraph","text":"2. Chicken eggs cooked"},{"type":"paragraph","text":"3. Fish processed and canned"},{"type":"paragraph","text":"4. Newspapers containing advertising material"},{"type":"paragraph","text":"Which of the above items is/are exempted under GST (Goods and Services Tax)?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"Fresh necessities and basic items like hulled cereal grains, cooked/raw eggs, and newspapers (even with ads) are placed under the nil (zero) tax rate and are exempted under GST. However, processed, cured, or canned fish is treated as a manufactured commercial good and is taxable at 5% GST.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-008","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":8,"booklet":"C","questionType":"MCQ","subject":"Environment","topic":"Biodiversity & conservation","question":"Consider the following statements:\\n\\n1. The definition of “Critical Wildlife Habitat” is incorporated in the Forest Rights Act, 2006.\\n\\n2. For the first time in India, Baigas have been given Habitat Rights.\\n\\n3. Union Ministry of Environment, Forest and Climate Change officially decides and declares Habitat Rights for Primitive and Vulnerable Tribal Groups in any part of India.\\n\\nWhich of the statements given above is/are correct?","options":{"a":"1 and 2 only","b":"2 and 3 only","c":"3 only","d":"1, 2 and 3"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Consider the following statements:"},{"type":"paragraph","text":"1. The definition of “Critical Wildlife Habitat” is incorporated in the Forest Rights Act, 2006."},{"type":"paragraph","text":"2. For the first time in India, Baigas have been given Habitat Rights."},{"type":"paragraph","text":"3. Union Ministry of Environment, Forest and Climate Change officially decides and declares Habitat Rights for Primitive and Vulnerable Tribal Groups in any part of India."},{"type":"paragraph","text":"Which of the statements given above is/are correct?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"\\"Critical Wildlife Habitat\\" is defined under the Forest Rights Act, 2006 (Statement 1 is correct).  The Baiga tribe in Madhya Pradesh became the first community in India to get habitat rights (Statement 2 is correct).  Habitat rights are determined and filed before the Gram Sabhas under the Ministry of Tribal Affairs guidelines, not MoEFCC (Statement 3 is incorrect).","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-009","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":9,"booklet":"C","questionType":"MCQ","subject":"Environment","topic":"Plant diseases","question":"Consider the following:\\n\\n1. Birds\\n\\n2. Dust blowing\\n\\n3. Rain\\n\\n4. Wind blowing\\n\\nWhich of the above spread plant diseases?","options":{"a":"1 and 3 only","b":"3 and 4 only","c":"1, 2 and 4 only","d":"1, 2, 3 and 4"},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Consider the following:"},{"type":"paragraph","text":"1. Birds"},{"type":"paragraph","text":"2. Dust blowing"},{"type":"paragraph","text":"3. Rain"},{"type":"paragraph","text":"4. Wind blowing"},{"type":"paragraph","text":"Which of the above spread plant diseases?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"Plant pathogens can be dispersed by birds, airborne dust, rain splashes and wind. All four listed agents can contribute to disease spread.","concept":"Plant diseases","references":[{"title":"UPSC CSE2018 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2018-prelims-gs1-c-010","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":10,"booklet":"C","questionType":"MCQ","subject":"Economy","topic":"Organic farming","question":"With reference to organic farming in India, consider the following statements:\\n\\n1. “The National Programme for Organic Production” (NPOP) is operated under the guidelines and directions of the Union Ministry of Rural Development.\\n\\n2. “The Agricultural and Processed Food Products Export Development Authority” (APEDA) functions as the Secretariat for the implementation of NPOP.\\n\\n3. Sikkim has become India’s first fully organic State.\\n\\nWhich of the statements given above is/are correct?","options":{"a":"1 and 2 only","b":"2 and 3 only","c":"3 only","d":"1, 2 and 3"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"With reference to organic farming in India, consider the following statements:"},{"type":"paragraph","text":"1. “The National Programme for Organic Production” (NPOP) is operated under the guidelines and directions of the Union Ministry of Rural Development."},{"type":"paragraph","text":"2. “The Agricultural and Processed Food Products Export Development Authority” (APEDA) functions as the Secretariat for the implementation of NPOP."},{"type":"paragraph","text":"3. Sikkim has become India’s first fully organic State."},{"type":"paragraph","text":"Which of the statements given above is/are correct?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"NPOP comes under the Ministry of Commerce and Industry, with APEDA acting as its secretariat. Sikkim became India’s first fully organic State. Statements 2 and 3 are correct.","concept":"Organic farming","references":[{"title":"UPSC CSE2018 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2018-prelims-gs1-c-011","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":11,"booklet":"C","questionType":"MCQ","subject":"Polity & Governance","topic":"Parliament & state legislatures","question":"Regarding Money Bill, which of the following statements is not correct?","options":{"a":"A bill shall be deemed to be a Money Bill if it contains only provisions relating to imposition, abolition, remission, alteration or regulation of any tax.","b":"A Money Bill has provisions for the custody of the Consolidated Fund of India or the Contingency Fund of India.","c":"A Money Bill is concerned with the appropriation of moneys out of the Contingency Fund of India.","d":"A Money Bill deals with the regulation of borrowing of money or giving of any guarantee by the Government of India."},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Regarding Money Bill, which of the following statements is not correct?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"Article 110 states that a Money Bill deals with the appropriation of money out of the Consolidated Fund of India, not the Contingency Fund (Statement c is incorrect).","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-012","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":12,"booklet":"C","questionType":"MCQ","subject":"Polity & Governance","topic":"Presidential electoral college","question":"With reference to the election of the President of India, consider the following statements:\\n\\n1. The value of the vote of each MLA varies from State to State.\\n\\n2. The value of the vote of MPs of the Lok Sabha is more than the value of the vote of MPs of the Rajya Sabha.\\n\\nWhich of the statements given above is/are correct?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"With reference to the election of the President of India, consider the following statements:"},{"type":"paragraph","text":"1. The value of the vote of each MLA varies from State to State."},{"type":"paragraph","text":"2. The value of the vote of MPs of the Lok Sabha is more than the value of the vote of MPs of the Rajya Sabha."},{"type":"paragraph","text":"Which of the statements given above is/are correct?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"The value of an MLA’s vote depends on the State’s population and number of elected MLAs. All elected MPs carry the same vote value, regardless of their House. Only statement 1 is correct.","concept":"Presidential electoral college","references":[{"title":"UPSC CSE2018 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2018-prelims-gs1-c-013","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":13,"booklet":"C","questionType":"MCQ","subject":"International Relations","topic":"IAEA safeguards","question":"In the Indian context, what is the implication of ratifying the ‘Additional Protocol’ with the ‘International Atomic Energy Agency (IAEA)’","options":{"a":"The civilian nuclear reactors come under IAEA safeguards.","b":"The military nuclear installations come under the inspection of IAEA.","c":"The country will have the privilege to buy uranium from the Nuclear Suppliers Group (NSG)","d":"The country automatically becomes a member of the NSG."},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"In the Indian context, what is the implication of ratifying the ‘Additional Protocol’ with the ‘International Atomic Energy Agency (IAEA)’"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"India’s Additional Protocol concerns its civilian nuclear safeguards framework. It does not put military installations under inspection or automatically confer NSG membership.","concept":"IAEA safeguards","references":[{"title":"UPSC CSE2018 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2018-prelims-gs1-c-014","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":14,"booklet":"C","questionType":"MCQ","subject":"International Relations","topic":"ASEAN free-trade partners","question":"Consider the following countries:\\n\\n1. Australia\\n\\n2. Canada\\n\\n3. China\\n\\n4. India\\n\\n5. Japan\\n\\n6. USA\\n\\nWhich of the above are among the ‘free trade partners’ of ASEAN?","options":{"a":"1, 2, 4 and 5","b":"3, 4, 5 and 6","c":"1, 3, 4 and 5","d":"2, 3, 4 and 6"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Consider the following countries:"},{"type":"paragraph","text":"1. Australia"},{"type":"paragraph","text":"2. Canada"},{"type":"paragraph","text":"3. China"},{"type":"paragraph","text":"4. India"},{"type":"paragraph","text":"5. Japan"},{"type":"paragraph","text":"6. USA"},{"type":"paragraph","text":"Which of the above are among the ‘free trade partners’ of ASEAN?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"In 2018, ASEAN had trade arrangements with Australia, China, India and Japan among the listed countries. Canada and the United States did not belong to that listed set.","concept":"ASEAN free-trade partners","references":[{"title":"UPSC CSE2018 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2018-prelims-gs1-c-015","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":15,"booklet":"C","questionType":"MCQ","subject":"Environment","topic":"Climate action & agreements","question":"With reference to the “Global Alliance for Climate-Smart Agriculture (GACSA)”, which of the following statements is/are correct?\\n\\n1. GACSA is an outcome of the Climate Summit held in Paris in 2015.\\n\\n2. Membership of GACSA does not create any binding obligations.\\n\\n3. India was instrumental in the creation of GACSA.\\n\\nSelect the correct answer using the code given below:","options":{"a":"1 and 3 only","b":"2 only","c":"2 and 3 only","d":"1, 2 and 3"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"With reference to the “Global Alliance for Climate-Smart Agriculture (GACSA)”, which of the following statements is/are correct?"},{"type":"paragraph","text":"1. GACSA is an outcome of the Climate Summit held in Paris in 2015."},{"type":"paragraph","text":"2. Membership of GACSA does not create any binding obligations."},{"type":"paragraph","text":"3. India was instrumental in the creation of GACSA."},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"GACSA was launched in 2014 during the UN Climate Summit in New York, not Paris 2015 (Statement 1 is incorrect).  It is an inclusive, voluntary multi-stakeholder platform that does not create binding obligations (Statement 2 is correct).  India is not a member of GACSA and was not instrumental in its creation (Statement 3 is incorrect).","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-016","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":16,"booklet":"C","questionType":"MCQ","subject":"Science & Technology","topic":"Applied science & technology","question":"Which of the following is/are the aim/aims of “Digital India” Plan of the Government of India?\\n\\n1. Formation of India’s own Internet companies like China did.\\n\\n2. Establish a policy framework to encourage overseas multinational corporations that collect Big Data to build their large data centres within our national geographical boundaries.\\n\\n3. Connect many of our villages to the Internet and bring Wi-Fi to many of our schools, public places and major tourist centres.\\n\\nSelect the correct answer using the code given below:","options":{"a":"1 and 2 only","b":"3 only","c":"2 and 3 only","d":"1, 2 and 3"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Which of the following is/are the aim/aims of “Digital India” Plan of the Government of India?"},{"type":"paragraph","text":"1. Formation of India’s own Internet companies like China did."},{"type":"paragraph","text":"2. Establish a policy framework to encourage overseas multinational corporations that collect Big Data to build their large data centres within our national geographical boundaries."},{"type":"paragraph","text":"3. Connect many of our villages to the Internet and bring Wi-Fi to many of our schools, public places and major tourist centres."},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"The primary vision of Digital India is to transform India into a digitally empowered society, focusing heavily on digital infrastructure like connecting villages with broadband and providing public Wi-Fi. Forming indigenous mega-corporations or exclusively establishing policy for foreign data centers are not stated aims.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-017","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":17,"booklet":"C","questionType":"MCQ","subject":"Geography","topic":"World geography & mapping","question":"Consider the following pairs:\\n\\nTowns sometimes mentioned in news - Country\\n\\n1. Aleppo – Syria\\n\\n2. Kirkuk – Yemen\\n\\n3. Mosul – Palestine\\n\\n4. Mazar-i-sharif – Afghanistan\\n\\nWhich of the pairs given above are correctly matched?","options":{"a":"1 and 2","b":"1 and 4","c":"2 and 3","d":"3 and 4"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Consider the following pairs:"},{"type":"paragraph","text":"Towns sometimes mentioned in news - Country"},{"type":"paragraph","text":"1. Aleppo – Syria"},{"type":"paragraph","text":"2. Kirkuk – Yemen"},{"type":"paragraph","text":"3. Mosul – Palestine"},{"type":"paragraph","text":"4. Mazar-i-sharif – Afghanistan"},{"type":"paragraph","text":"Which of the pairs given above are correctly matched?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"Pair 1 is correctly matched. Aleppo is a city in northern Syria. It used to be largest city of Syria before civil war broke out in 2011. Pair 2 and 3 are incorrectly matched. Kirkuk and Mosul are cities located in Iraq. Kikuk is a region in Iraq which is claimed by the Kurds, who controlled it for a brief period in 2017. Mosul, located in Iraq witnessed major battles to defeat ISIS. Mosul was retaken from ISIS in 2017. Pair 4 is correctly matched. Mazar-i-sharif is a city in Afghanistan, which witnessed a massive Taliban attack on Afghanistan Armed Forces in 2017. Also, Indian consulate in Mazar-i-Sharif was attacked in 2016. Thus, all the places mentioned in the options are conflict ridden areas.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-018","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":18,"booklet":"C","questionType":"MCQ","subject":"History","topic":"Government of India Act1935","question":"In the Federation established by the Government of India Act of 1935, residuary powers were given to the","options":{"a":"Federal Legislature","b":"Governor General","c":"Provincial Legislature","d":"Provincial Governors"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"In the Federation established by the Government of India Act of 1935, residuary powers were given to the"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"The 1935 Act assigned residuary legislative powers to the Governor-General. The proposed federation itself did not come into operation.","concept":"Government of India Act1935","references":[{"title":"UPSC CSE2018 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2018-prelims-gs1-c-019","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":19,"booklet":"C","questionType":"MCQ","subject":"Polity & Governance","topic":"Parliament & state legislatures","question":"Consider the following statements:\\n\\n1. The Speaker of the legislative Assembly shall vacate his/her office if he/she ceases to be a member of the Assembly.\\n\\n2. Whenever the Legislative Assembly is dissolved, the Speaker shall vacate his/her office immediately.\\n\\nWhich of the statements given above is/are correct?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Consider the following statements:"},{"type":"paragraph","text":"1. The Speaker of the legislative Assembly shall vacate his/her office if he/she ceases to be a member of the Assembly."},{"type":"paragraph","text":"2. Whenever the Legislative Assembly is dissolved, the Speaker shall vacate his/her office immediately."},{"type":"paragraph","text":"Which of the statements given above is/are correct?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"Under Article 179, the Speaker shall vacate office if they cease to be a member of the Assembly (Statement 1 is correct). However, the Speaker does not vacate office immediately upon dissolution, but continues until just before the first meeting of the newly elected Assembly (Statement 2 is incorrect).","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-020","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":20,"booklet":"C","questionType":"MCQ","subject":"Polity & Governance","topic":"Rights, duties & directive principles","question":"Which one of the following reflects the most appropriate relationship between law and liberty?","options":{"a":"If there are more laws, there is less liberty.","b":"If there are no laws, there is no liberty","c":"If there is liberty, laws have to be made by the people.","d":"If laws are changed too often, liberty is in danger."},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Which one of the following reflects the most appropriate relationship between law and liberty?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"Liberty is protected by law. The more law there is, the more liberty there is. As soon as law ends, liberty also ceases to exist.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-021","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":21,"booklet":"C","questionType":"MCQ","subject":"Polity & Governance","topic":"Union & state executive","question":"Consider the following statements:\\n\\n1. No criminal proceedings shall be instituted against the Governor of a State in any court during his term of office.\\n\\n2. The emoluments and allowances of the Governor of a State shall not be diminished during his term of the office.\\n\\nWhich of the statements given above is/are correct?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Consider the following statements:"},{"type":"paragraph","text":"1. No criminal proceedings shall be instituted against the Governor of a State in any court during his term of office."},{"type":"paragraph","text":"2. The emoluments and allowances of the Governor of a State shall not be diminished during his term of the office."},{"type":"paragraph","text":"Which of the statements given above is/are correct?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"Article 361(2) grants immunity from criminal proceedings to the Governor during his term. Article 158(4) prevents the diminution of the Governor's emoluments and allowances during his term.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-022","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":22,"booklet":"C","questionType":"MCQ","subject":"Art & Culture","topic":"Art, architecture & monuments","question":"The well-known painting “Bani Thani” belongs to the","options":{"a":"Bundi School","b":"Jaipur School","c":"Kangra School","d":"Kishangarh School"},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"The well-known painting “Bani Thani” belongs to the"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"\\"Bani Thani\\" is a celebrated miniature painting of the Kishangarh school of Rajasthan, painted by artist Nihal Chand under the patronage of King Savant Singh. It is often referred to as India's \\"Mona Lisa\\".","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-023","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":23,"booklet":"C","questionType":"MCQ","subject":"Science & Technology","topic":"Applied science & technology","question":"What is “Terminal High Altitude Area Defense (THAAD)”, sometimes seen in the news?","options":{"a":"An Israeli radar system","b":"India’s indigenous anti-missile Programme","c":"An American anti-missile system","d":"A defence collaboration between Japan and South Korea"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"What is “Terminal High Altitude Area Defense (THAAD)”, sometimes seen in the news?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"THAAD is an advanced American anti-ballistic missile defense system designed to intercept and destroy short, medium, and intermediate-range ballistic missiles in their terminal phase.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-024","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":24,"booklet":"C","questionType":"MCQ","subject":"History & Culture","topic":"Bhakti composers","question":"With reference to cultural history of India, consider the following statements:\\n\\n1. Most of the Tyagaraja Kritis are devotional songs in Praise of Lord Krishna.\\n\\n2. Tyagaraja created several new ragas.\\n\\n3. Annamacharya and Tyagaraja are contemporaries.\\n\\n4. Annamacharya kirtanas are devotional songs in praise of Lord Venkateshwara.\\n\\nWhich of the statements given above are correct?","options":{"a":"1 and 3 only","b":"2 and 4 only","c":"1, 2 and 3","d":"2, 3 and 4"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"With reference to cultural history of India, consider the following statements:"},{"type":"paragraph","text":"1. Most of the Tyagaraja Kritis are devotional songs in Praise of Lord Krishna."},{"type":"paragraph","text":"2. Tyagaraja created several new ragas."},{"type":"paragraph","text":"3. Annamacharya and Tyagaraja are contemporaries."},{"type":"paragraph","text":"4. Annamacharya kirtanas are devotional songs in praise of Lord Venkateshwara."},{"type":"paragraph","text":"Which of the statements given above are correct?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"Tyagaraja composed mainly in praise of Lord Rama and created several ragas. Annamacharya’s compositions praise Lord Venkateshwara. They lived centuries apart, so statements 2 and 4 are correct.","concept":"Bhakti composers","references":[{"title":"UPSC CSE2018 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2018-prelims-gs1-c-025","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":25,"booklet":"C","questionType":"MCQ","subject":"Polity & Governance","topic":"Constitutional history & foundations","question":"Which of the following are regarded as the main features of the “Rule of Law”?\\n\\n1. Limitation of powers\\n\\n2. Equality before law\\n\\n3. People’s responsibility to the Government\\n\\n4. Liberty and civil rights\\n\\nSelect the correct answer using the code given below:","options":{"a":"1 and 3 only","b":"2 and 4 only","c":"1, 2 and 4 only","d":"1, 2, 3 and 4"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Which of the following are regarded as the main features of the “Rule of Law”?"},{"type":"paragraph","text":"1. Limitation of powers"},{"type":"paragraph","text":"2. Equality before law"},{"type":"paragraph","text":"3. People’s responsibility to the Government"},{"type":"paragraph","text":"4. Liberty and civil rights"},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"Rule of Law implies equality before law, limitation of powers, and safeguarding liberty and civil rights (1, 2, and 4). People's responsibility to the government is not a feature of the Rule of Law.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-026","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":26,"booklet":"C","questionType":"MCQ","subject":"History","topic":"Colonial education policy","question":"Which of the following led to the introduction of English Education in India?\\n\\n1. Charter Act of 1813\\n\\n2. General Committee of Public Instruction, 1823\\n\\n3. Orientalist and Anglicist Controversy\\n\\nSelect the correct answer using the code given below:","options":{"a":"1 and 2 only","b":"2 only","c":"1 and 3 only","d":"1, 2 and 3"},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Which of the following led to the introduction of English Education in India?"},{"type":"paragraph","text":"1. Charter Act of 1813"},{"type":"paragraph","text":"2. General Committee of Public Instruction, 1823"},{"type":"paragraph","text":"3. Orientalist and Anglicist Controversy"},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"The Charter Act 1813 established a funding basis for education, the General Committee of Public Instruction organised policy, and the Orientalist-Anglicist debate shaped the move toward English education. All three contributed.","concept":"Colonial education policy","references":[{"title":"UPSC CSE2018 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2018-prelims-gs1-c-027","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":27,"booklet":"C","questionType":"MCQ","subject":"Geography","topic":"Indian lakes","question":"Which one of the following is an artificial lake?","options":{"a":"Kodaikanal (Tamil Nadu)","b":"Kolleru (Andhra Pradesh)","c":"Nainital (Uttarakhand)","d":"Renuka (Himachal Pradesh)"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Which one of the following is an artificial lake?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"Kodaikanal Lake was created artificially in the nineteenth century. Kolleru, Nainital and Renuka are natural lakes.","concept":"Indian lakes","references":[{"title":"UPSC CSE2018 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2018-prelims-gs1-c-028","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":28,"booklet":"C","questionType":"MCQ","subject":"Social Development","topic":"PMKVY","question":"With reference to Pradhan Mantri Kaushal Vikas Yojana, consider the following statements:\\n\\n1. It is the flagship scheme of the Ministry of Labour and Employment.\\n2. It, among other things, will also impart training in soft skills, entrepreneurship, financial and digital literacy.\\n3. It aims to align the competencies of the unregulated workforce of the country to the National Skill Qualification Framework.\\n\\nWhich of the statements given above is/are correct?","options":{"a":"1 and 3 only","b":"2 only","c":"2 and 3 only","d":"1, 2 and 3"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"With reference to Pradhan Mantri Kaushal Vikas Yojana, consider the following statements:"},{"type":"paragraph","text":"1. It is the flagship scheme of the Ministry of Labour and Employment.\\n2. It, among other things, will also impart training in soft skills, entrepreneurship, financial and digital literacy.\\n3. It aims to align the competencies of the unregulated workforce of the country to the National Skill Qualification Framework."},{"type":"paragraph","text":"Which of the statements given above is/are correct?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"PMKVY is a Ministry of Skill Development and Entrepreneurship scheme, not a Labour Ministry flagship. It includes soft skills and literacy and aligns informal workers’ competencies with NSQF. Statements 2 and 3 are correct.","concept":"PMKVY","references":[{"title":"UPSC CSE2018 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2018-prelims-gs1-c-029","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":29,"booklet":"C","questionType":"MCQ","subject":"History","topic":"Modern India · Gandhian & mass movements","question":"In 1920, which of the following changed its name to “Swarajya Sabha”?","options":{"a":"All India Home Rule League","b":"Hindu Mahasabha","c":"South Indian Liberal Federation","d":"The Servants of India Society"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"In 1920, which of the following changed its name to “Swarajya Sabha”?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"In 1920, when Mahatma Gandhi and his followers gained control of the All India Home Rule League, they changed its name to 'Swaraj Sabha' to align it with the Non-Cooperation Movement.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-030","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":30,"booklet":"C","questionType":"MCQ","subject":"History","topic":"Nineteenth-century chronology","question":"Which among the following events happened earliest?","options":{"a":"Swami Dayanand established Arya Samaj","b":"Dinabandhu Mitra wrote Neeldarpan","c":"Bankim Chandra Chattopadhyay wrote Anandamath","d":"Satyendranath Tagore became the first Indian to succeed in the Indian Civil Services Examination."},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Which among the following events happened earliest?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"Dinabandhu Mitra’s Nil Darpan appeared in 1860. Satyendranath Tagore qualified for the ICS in 1863, Arya Samaj was founded in 1875, and Anandamath appeared in 1882, so Nil Darpan is earliest.","concept":"Nineteenth-century chronology","references":[{"title":"UPSC CSE2018 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2018-prelims-gs1-c-031","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":31,"booklet":"C","questionType":"MCQ","subject":"Environment","topic":"Pollution & waste","question":"Which of the following is/are the possible consequence/s of heavy sand mining in riverbeds?\\n\\n1. Decreased salinity in the river\\n\\n2. Pollution of groundwater\\n\\n3. Lowering of the water-table\\n\\nSelect the correct answer using the code given below:","options":{"a":"1 only","b":"2 and 3 only","c":"1 and 3 only","d":"1, 2 and 3"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Which of the following is/are the possible consequence/s of heavy sand mining in riverbeds?"},{"type":"paragraph","text":"1. Decreased salinity in the river"},{"type":"paragraph","text":"2. Pollution of groundwater"},{"type":"paragraph","text":"3. Lowering of the water-table"},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"Sand mining can actually increase (not decrease) the salinity of rivers by removing sand that acts as a natural filter.  It directly leads to the pollution of groundwater and lowers the water table by removing the sand that stores water like a sponge.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-032","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":32,"booklet":"C","questionType":"MCQ","subject":"Environment","topic":"Agricultural soils","question":"With reference to agricultural soils, consider the following statements:\\n\\n1. A high content of organic matter in soil drastically reduces its water holding capacity\\n\\n2. Soil does not play any role in the sulphur cycle\\n\\n3. Irrigation over a period of time can contribute to the salinization of some agricultural lands.\\n\\nWhich of the statements given above is/are correct?","options":{"a":"1 and 2 only","b":"3 only","c":"1 and 3 only","d":"1, 2 and 3"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"With reference to agricultural soils, consider the following statements:"},{"type":"paragraph","text":"1. A high content of organic matter in soil drastically reduces its water holding capacity"},{"type":"paragraph","text":"2. Soil does not play any role in the sulphur cycle"},{"type":"paragraph","text":"3. Irrigation over a period of time can contribute to the salinization of some agricultural lands."},{"type":"paragraph","text":"Which of the statements given above is/are correct?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"Organic matter generally improves water retention, and soil participates in sulphur cycling. Irrigation can cause salts to accumulate when drainage and leaching are inadequate. Only statement 3 is correct.","concept":"Agricultural soils","references":[{"title":"UPSC CSE2018 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2018-prelims-gs1-c-033","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":33,"booklet":"C","questionType":"MCQ","subject":"Environment","topic":"Climate action & agreements","question":"The Partnership for Action on Green Economy (PAGE), a UN mechanism to assist countries transition towards greener and more inclusive economies, emerged at","options":{"a":"The Earth Summit on Sustainable Development 2002, Johannesburg","b":"The United Nations Conference on Sustainable Development 2012, Rio de Janeiro","c":"The United Nations Framework Convention on Climate Change 2015, Paris","d":"The World Sustainable Development Summit 2016, New Delhi"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"The Partnership for Action on Green Economy (PAGE), a UN mechanism to assist countries transition towards greener and more inclusive economies, emerged at"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"The Partnership for Action on Green Economy (PAGE) was launched in 2013 as a direct response to the call at the United Nations Conference on Sustainable Development 2012 (Rio+20) to support countries wishing to embark on greener and more inclusive growth trajectories.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-034","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":34,"booklet":"C","questionType":"MCQ","subject":"Science & Technology","topic":"Applied science & technology","question":"“3D printing” has application in which of the following?\\n\\n1. Preparation of confectionery items\\n\\n2. Manufacture of bionic ears\\n\\n3. Automotive Industry\\n\\n4. Reconstruction surgeries\\n\\n5. Data processing technologies\\n\\nSelect the correct answer using the code given below:","options":{"a":"1, 3 and 4 only","b":"2, 3 and 5 only","c":"1 and 4 only","d":"1, 2, 3, 4 and 5"},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"“3D printing” has application in which of the following?"},{"type":"paragraph","text":"1. Preparation of confectionery items"},{"type":"paragraph","text":"2. Manufacture of bionic ears"},{"type":"paragraph","text":"3. Automotive Industry"},{"type":"paragraph","text":"4. Reconstruction surgeries"},{"type":"paragraph","text":"5. Data processing technologies"},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"3D printing is a highly versatile manufacturing process that has found applications in food (confectionery), medical fields (bionic ears, surgeries), engineering (automotive), and even producing components like circuit boards for data processing.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-035","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":35,"booklet":"C","questionType":"MCQ","subject":"Geography","topic":"India Physical Environment","question":"Consider the following statements:\\n\\n1. The Barren Island volcano is an active volcano located in the Indian Territory.\\n\\n2. Barren Island lies about 140 km east of Great Nicobar\\n\\n3. The last time the Barren Island volcano erupted was in 1991 and it has remained inactive since then.\\n\\nWhich of the statements given above is/are correct?","options":{"a":"1 only","b":"2 and 3","c":"3 only","d":"1 and 3"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Consider the following statements:"},{"type":"paragraph","text":"1. The Barren Island volcano is an active volcano located in the Indian Territory."},{"type":"paragraph","text":"2. Barren Island lies about 140 km east of Great Nicobar"},{"type":"paragraph","text":"3. The last time the Barren Island volcano erupted was in 1991 and it has remained inactive since then."},{"type":"paragraph","text":"Which of the statements given above is/are correct?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"Statement 1 is correct. Barren Island is an active volcano located in the Andaman Sea in the Union territory of Andaman and Nicobar Islands. It is the only confirmed active volcano of India and South Asia. It is a stratovolcano composed of lava, rock fragments, and volcanic ash. It lies over the fault whose movement caused the tsunami on December 26, 2004. Statement 2 is incorrect. It lies about 140km northeast of Port Blair, the capital of Andaman and Nicobar Islands. It lies north of Great Nicobar. It is a tourist destination, and surrounded by waters ideal for scuba diving andis home to a wide variety of aquatic life. Statement 3 is incorrect. Historically, the first record of the volcano’s eruption dates back to 1787. It was known to have erupted at least five times over the next 100 years. Then there was silence for a century. In 1991, it spewed so massively that smoke billowed out for about six months. Ever since, there have been eruptions every two-three year. In the recent past,it erupted in February 2016 andin January 2017.","concept":"India Physical Environment","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-036","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":36,"booklet":"C","questionType":"MCQ","subject":"Environment","topic":"Biodiversity & conservation","question":"Why is a plant called Prosopis Juliflora often mentioned in news?","options":{"a":"Its extract is widely used in cosmetics","b":"It tends to reduce the biodiversity in the area in which it grows.","c":"Its extract is used in the synthesis of pesticides.","d":"None of the above."},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Why is a plant called Prosopis Juliflora often mentioned in news?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"Prosopis juliflora is an exotic, highly invasive tree species in India that outcompetes native flora, significantly reducing the biodiversity in the habitats where it aggressively grows.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-037","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":37,"booklet":"C","questionType":"MCQ","subject":"Environment","topic":"Ecology & environment","question":"Consider the following statements:\\n\\n1. Most of the world’s coral reefs are in tropical waters.\\n\\n2. More than one-third of the world’s coral reefs are located in the territories of Australia, Indonesia and Philippines.\\n\\n3. Coral reefs host far more number of animal phyla than those hosted by tropical rainforests.\\n\\nWhich of the statements given above is/are correct?","options":{"a":"1 and 2 only","b":"3 only","c":"1 and 3 only","d":"1, 2 and 3"},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Consider the following statements:"},{"type":"paragraph","text":"1. Most of the world’s coral reefs are in tropical waters."},{"type":"paragraph","text":"2. More than one-third of the world’s coral reefs are located in the territories of Australia, Indonesia and Philippines."},{"type":"paragraph","text":"3. Coral reefs host far more number of animal phyla than those hosted by tropical rainforests."},{"type":"paragraph","text":"Which of the statements given above is/are correct?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"Most coral reefs are in tropical waters between the Tropics of Cancer and Capricorn (Statement 1 is correct). Indonesia, Australia, and the Philippines host almost 44% of the world's coral reefs (Statement 2 is correct). Coral reefs host 32 of the 34 animal phyla, compared to only 9 in tropical rainforests (Statement 3 is correct).","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-038","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":38,"booklet":"C","questionType":"MCQ","subject":"Environment","topic":"Climate action & agreements","question":"“Momentum for Change: Climate Neutral Now” is an initiative launched by","options":{"a":"The Intergovernmental Panel on Climate Change","b":"The UNEP Secretariat","c":"The UNFCCC Secretariat","d":"The World Meteorological Organization"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"“Momentum for Change: Climate Neutral Now” is an initiative launched by"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"The UNFCCC secretariat launched the Climate Neutral Now initiative in 2015 to enhance climate action by engaging non-Party stakeholders (like companies and individuals) to measure, reduce, and offset their climate footprints.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-039","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":39,"booklet":"C","questionType":"MCQ","subject":"History","topic":"Colonial educational institutions","question":"With reference to educational institutions during colonial rule in India, Consider the following pairs:\\n\\n| Institution | Founder\\n\\n1. | Sanskrit College at Benaras | William Jones\\n\\n2. | Calcutta Madarsa | Warren Hastings\\n\\n3. | Fort William College | Arthur Wellesley\\n\\nWhich of the pairs given above is/are correct?","options":{"a":"1 and 2","b":"2 only","c":"1 and 3","d":"3 only"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"With reference to educational institutions during colonial rule in India, Consider the following pairs:"},{"type":"table","headers":["No.","Institution","Founder"],"rows":[["1.","Sanskrit College at Benaras","William Jones"],["2.","Calcutta Madarsa","Warren Hastings"],["3.","Fort William College","Arthur Wellesley"]]},{"type":"paragraph","text":"Which of the pairs given above is/are correct?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"Calcutta Madrasa was founded under Warren Hastings. Sanskrit College at Benaras was established through Jonathan Duncan, and Fort William College by Governor-General Richard Wellesley, not Arthur Wellesley. Only pair 2 is correct.","concept":"Colonial educational institutions","references":[{"title":"UPSC CSE2018 final key · SeriesC","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3"}]},"sourceNotes":"Editorial study note checked against the final key’s correct option; UPSC publishes the answer key, not these explanations."},{"id":"upsc-2018-prelims-gs1-c-040","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":40,"booklet":"C","questionType":"MCQ","subject":"Geography","topic":"World geography & mapping","question":"Consider the following pairs:\\n\\n| Regions sometimes mentioned In news | Country\\n\\n1. | Catalonia | Spain\\n\\n2. | Crimea | Hungary\\n\\n3. | Mindanao | Philippines\\n\\n4. | Oromia | Nigeria\\n\\nWhich of the pairs given above are correctly matched?","options":{"a":"1, 2 and 3 only","b":"3 and 4 only","c":"1 and 3 only","d":"2 and 4 only"},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Consider the following pairs:"},{"type":"table","headers":["No.","Regions sometimes mentioned In news","Country"],"rows":[["1.","Catalonia","Spain"],["2.","Crimea","Hungary"],["3.","Mindanao","Philippines"],["4.","Oromia","Nigeria"]]},{"type":"paragraph","text":"Which of the pairs given above are correctly matched?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"All the regions mentioned have been in news for seeking autonomy from the countries they are located in. Pair 1 is correct. Catalonia is a autonomous region in Spain. They are seeking complete independence. Pair 2 is incorrect. Till 2014, Crimea was part of Ukraine. Following pro-Russian demonstrations, it was annexed by Russia. Pair 3 is correct. Mindanao is an Island in Philippines. Centuries of conquest first by Spanish and American colonial forces that had ruled the Philippine archipelago followed by Filipino Christian settlers have gradually turned Muslims into a minority group in Mindanao, triggering conflict over land, resources and sharing of political power. Pair 4 is incorrect. Oromia is a state in Ethiopia, which has seen struggle for autonomy in the past by the Oromo people.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-041","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":41,"booklet":"C","questionType":"MCQ","subject":"Science & Technology","topic":"Applied science & technology","question":"With reference to the Indian Regional Navigation Satellite System (IRNSS), consider the following statements:\\n\\n1. IRNSS has three satellites in geostationary and four satellites in geosynchronous orbits.\\n\\n2. IRNSS covers entire India and about 5500 sq km beyond its borders.\\n\\n3. India will have its own satellite navigation system with full global coverage by the middle of 2019.\\n\\nWhich of the statements given above is/are correct?","options":{"a":"1 only","b":"1 and 2 only","c":"2 and 3 only","d":"None"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"With reference to the Indian Regional Navigation Satellite System (IRNSS), consider the following statements:"},{"type":"paragraph","text":"1. IRNSS has three satellites in geostationary and four satellites in geosynchronous orbits."},{"type":"paragraph","text":"2. IRNSS covers entire India and about 5500 sq km beyond its borders."},{"type":"paragraph","text":"3. India will have its own satellite navigation system with full global coverage by the middle of 2019."},{"type":"paragraph","text":"Which of the statements given above is/are correct?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"IRNSS (NavIC) consists of 7 satellites (3 geostationary and 4 geosynchronous). Its primary service area extends up to 1500 km (not 5500 km) beyond India's borders, and it is a regional system, not a global one like GPS.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-042","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":42,"booklet":"C","questionType":"MCQ","subject":"Science & Technology","topic":"General science · collection 1","question":"Consider the following phenomena:\\n\\n1. Light is affected by gravity.\\n\\n2. The Universe is constantly expanding.\\n\\n3. Matter warps its surrounding space-time.\\n\\nWhich of the above is/are the prediction/predictions of Albert Einstein’s General Theory of Relativity, often discussed in media?","options":{"a":"1 and 2 only","b":"3 only","c":"1 and 3 only","d":"1, 2 and 3"},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Consider the following phenomena:"},{"type":"paragraph","text":"1. Light is affected by gravity."},{"type":"paragraph","text":"2. The Universe is constantly expanding."},{"type":"paragraph","text":"3. Matter warps its surrounding space-time."},{"type":"paragraph","text":"Which of the above is/are the prediction/predictions of Albert Einstein’s General Theory of Relativity, often discussed in media?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"According to Albert Einstein's General Theory of Relativity, matter warps space-time, light is affected by gravity, and the universe is expanding.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-043","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":43,"booklet":"C","questionType":"MCQ","subject":"Science & Technology","topic":"Applied science & technology","question":"With reference to the Genetically Modified mustard (GM mustard) developed in India, consider the following statements:\\n\\n1. GM mustard has the genes of a soil bacterium that give the plant the property of pest-resistance to a wide variety of pests.\\n\\n2. GM mustard has the genes that allow the plant cross-pollination and hybridization.\\n\\n3. GM mustard has been developed jointly by the IARI and Punjab Agricultural University.\\n\\nWhich of the statements given above is/are correct?","options":{"a":"1 and 3 only","b":"2 only","c":"2 and 3 only","d":"1, 2 and 3"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"With reference to the Genetically Modified mustard (GM mustard) developed in India, consider the following statements:"},{"type":"paragraph","text":"1. GM mustard has the genes of a soil bacterium that give the plant the property of pest-resistance to a wide variety of pests."},{"type":"paragraph","text":"2. GM mustard has the genes that allow the plant cross-pollination and hybridization."},{"type":"paragraph","text":"3. GM mustard has been developed jointly by the IARI and Punjab Agricultural University."},{"type":"paragraph","text":"Which of the statements given above is/are correct?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"GM mustard (DMH-11) is engineered to allow cross-pollination (heterosis breeding) to create higher yield hybrids (Statement 2 is correct). It does not have Bt genes for pest resistance, and it was developed by Delhi University's CGMCP, not IARI/Punjab Ag University.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-044","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":44,"booklet":"C","questionType":"MCQ","subject":"Science & Technology","topic":"Applied science & technology","question":"Consider the following pairs:\\n\\nTerms sometimes seen in news - Context/Topic\\n\\n1. Belle II experiment – Artificial Intelligence\\n\\n2. Blockchain technology – Digital/Cryptocurrency\\n\\n3. CRISPR – Cas9 – Particle Physics\\n\\nWhich of the pairs given above is/are correctly matched?","options":{"a":"1 and 2 only","b":"2 only","c":"2 and 3 only","d":"1, 2 and 3"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Consider the following pairs:"},{"type":"paragraph","text":"Terms sometimes seen in news - Context/Topic"},{"type":"paragraph","text":"1. Belle II experiment – Artificial Intelligence"},{"type":"paragraph","text":"2. Blockchain technology – Digital/Cryptocurrency"},{"type":"paragraph","text":"3. CRISPR – Cas9 – Particle Physics"},{"type":"paragraph","text":"Which of the pairs given above is/are correctly matched?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"Belle II is a particle physics experiment, and CRISPR-Cas9 is a genome editing tool in biology (Pairs 1 and 3 are swapped/incorrect). Blockchain technology is correctly matched with digital/cryptocurrency.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-045","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":45,"booklet":"C","questionType":"MCQ","subject":"Environment","topic":"Climate change","question":"Which of the following statements best describes “carbon fertilization”?","options":{"a":"Increased plant growth due to increased concentration of carbon dioxide in the atmosphere","b":"Increased temperature of Earth due to increased concentration of carbon dioxide in the atmosphere","c":"Increased acidity of oceans as a result of increased concentration of carbon dioxide in the atmosphere","d":"Adaptation of all living beings on Earth to the climate change brought about by the increased concentration of carbon dioxide in the atmosphere"},"answer":"a","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Which of the following statements best describes “carbon fertilization”?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"Carbon fertilization (or the Carbon Fertilization Effect) describes the phenomenon where increased levels of carbon dioxide in the atmosphere lead to an increased rate of photosynthesis, which subsequently causes increased plant growth.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-046","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":46,"booklet":"C","questionType":"MCQ","subject":"Science & Technology","topic":"Applied science & technology","question":"When the alarm of your smartphone rings in the morning, you wake up and tap it to stop the alarm which causes your geyser to be switched on automatically. The smart mirror in your bathroom shows the day’s weather and also indicates the level of water in your overhead tank. After you take some groceries from your refrigerator for making breakfast, it recognises the shortage of stock in it and places an order for the supply of fresh grocery items. When you step out of your house and lock the door, all lights, fans, geysers and AC machines get switched off automatically. On your way to office, your car warns you about traffic congestion ahead and suggests an alternative route, and if you are late for a meeting, it sends a message to your office accordingly.\\n\\nIn the context of emerging communication technologies, which one of the following terms best applies to the above scenario?","options":{"a":"Border Gateway Protocol","b":"Internet of things","c":"Internet protocol","d":"Virtual private network"},"answer":"b","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"When the alarm of your smartphone rings in the morning, you wake up and tap it to stop the alarm which causes your geyser to be switched on automatically. The smart mirror in your bathroom shows the day’s weather and also indicates the level of water in your overhead tank. After you take some groceries from your refrigerator for making breakfast, it recognises the shortage of stock in it and places an order for the supply of fresh grocery items. When you step out of your house and lock the door, all lights, fans, geysers and AC machines get switched off automatically. On your way to office, your car warns you about traffic congestion ahead and suggests an alternative route, and if you are late for a meeting, it sends a message to your office accordingly."},{"type":"paragraph","text":"In the context of emerging communication technologies, which one of the following terms best applies to the above scenario?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"The scenario describes physical objects (mirrors, geysers, refrigerators, cars) embedded with sensors and software, connecting and exchanging data over a network, which is the exact definition of the Internet of Things (IoT).","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-047","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":47,"booklet":"C","questionType":"MCQ","subject":"Science & Technology","topic":"Applied science & technology","question":"With reference to solar power production in India, Consider the following statements:\\n\\n1. India is the third largest in the world in the manufacture of silicon wafers used in Photovoltaic units.\\n\\n2. The solar power tariffs are determined by the Solar Energy Corporation of India.\\n\\nWhich of the statements given above is /are correct?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"With reference to solar power production in India, Consider the following statements:"},{"type":"paragraph","text":"1. India is the third largest in the world in the manufacture of silicon wafers used in Photovoltaic units."},{"type":"paragraph","text":"2. The solar power tariffs are determined by the Solar Energy Corporation of India."},{"type":"paragraph","text":"Which of the statements given above is /are correct?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"India currently imports almost all of its silicon wafers and does not have a large domestic manufacturing base for them. Solar power tariffs are determined by the respective State Electricity Regulatory Commissions (SERCs) or CERC, not SECI.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-048","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":48,"booklet":"C","questionType":"MCQ","subject":"History","topic":"Modern India · European expansion & colonial rule","question":"The staple commodities of export by the English East India Company from Bengal in the middle of the 18th century were","options":{"a":"Raw cotton, oil seeds and opium","b":"Sugar, salt, Zinc and lead","c":"Copper, Silver, gold, spices and tea","d":"Cotton, Silk, saltpetre and Opium"},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"The staple commodities of export by the English East India Company from Bengal in the middle of the 18th century were"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"Fine qualities of cotton and silk from Bengal, along with saltpetre (used in gunpowder production) from Bihar and Bengal, and opium exported to China, formed the primary export commodities of the East India Company during the mid-18th century.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-049","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":49,"booklet":"C","questionType":"MCQ","subject":"History","topic":"Modern India · Gandhian & mass movements","question":"Which one of the following is a very significant aspect of the Champaran Satyagraha?","options":{"a":"Active all- India participation of lawyers, students and women in the National Movement.","b":"Active involvement of Dalit and Tribal Communities of India in the National Movement.","c":"Joining of peasant unrest to India’s National Movement.","d":"Drastic decrease in the cultivation of plantation crops and commercial crops."},"answer":"c","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Which one of the following is a very significant aspect of the Champaran Satyagraha?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"Champaran Satyagraha (1917) was Gandhi's first civil disobedience movement in India, and its most significant aspect was integrating localized peasant unrest against European indigo planters into the broader Indian National Movement.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."},{"id":"upsc-2018-prelims-gs1-c-050","year":2018,"stage":"Prelims","paper":"Prelims GS-I","number":50,"booklet":"C","questionType":"MCQ","subject":"History","topic":"Modern India · people, publications & events","question":"Who among the following were the founders of the “Hind Mazdoor Sabha” established in 1948?","options":{"a":"B. Krishna Pillai, E.M.S. Namboodiripad and K.C. George","b":"Jayaprakash Narayan, Deen Dayal Upadhyay and M.N. Roy","c":"C.P. Ramaswamy Iyer, K. Kamaraj and Veeresalingam Pantulu","d":"Ashok Mehta, T.S. Ramanujam and G.G. Mehta"},"answer":"d","keyStatus":"official","marks":2,"negativeMarks":0.6666666666666666,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2018-gs-set-c","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2018-GS-1.pdf#page=3","page":0,"blocks":[{"type":"paragraph","text":"Who among the following were the founders of the “Hind Mazdoor Sabha” established in 1948?"}],"sourceTitle":"UPSC CSE 2018 General Studies Paper I · Series C","explanation":{"justification":"The \\"Hind Mazdoor Sabha\\" (HMS) was founded in Howrah in 1948 by socialists dissatisfied with INTUC. Its founders included Ashok Mehta (General Secretary), T.S. Ramanujam, G.G. Mehta, R.S. Ruikar (President), Basawan Singh, and others.","concept":"","references":[]},"sourceNotes":"Editorial study note matched by question wording and the final key’s correct-option wording; the UPSC final key controls scoring."}]`);export{e as p};
